// @ts-check
import { defineConfig } from 'astro/config';
import cloudflare from '@astrojs/cloudflare';
import tailwindcss from '@tailwindcss/vite';

// Full-stack storefront: every route is server-rendered at the edge so the catalog
// is always read live from D1 (the `DB` binding) instead of a build-time snapshot.
export default defineConfig({
  // The canonical origin: feeds `Astro.site` and absolute URL construction.
  //
  // The sitemap is NOT generated by @astrojs/sitemap. Every route here is
  // `prerender = false`, so a build-time generator has no pages to enumerate and
  // can only emit route patterns like `/plugin/[id]` — which are not real URLs.
  // `src/pages/sitemap.xml.ts` instead enumerates the live D1 catalog at request
  // time, which is the only place the real ids exist.
  site: 'https://openrom-store.pages.dev',
  output: 'server',
  adapter: cloudflare({
    // Emulate the D1 binding from wrangler.toml during `astro dev`.
    platformProxy: {
      enabled: true,
      configPath: 'wrangler.toml',
      persist: { path: './.wrangler/state/v3' },
    },
  }),
  vite: {
    plugins: [tailwindcss()],
  },
});
